def solve(matrix):
    """Determinant of a square integer matrix. Empty matrix -> 1.
    Exact integer arithmetic: cofactor expansion for small n, Bareiss
    fraction-free elimination for large n."""
    if not matrix or not matrix[0]:
        return 1
    n = len(matrix)
    M = [list(row) for row in matrix]

    if n >= 9:
        sign = 1
        prev = 1
        for k in range(n - 1):
            if M[k][k] == 0:
                for i in range(k + 1, n):
                    if M[i][k] != 0:
                        M[k], M[i] = M[i], M[k]
                        sign = -sign
                        break
                else:
                    return 0
            for i in range(k + 1, n):
                for j in range(k + 1, n):
                    M[i][j] = (M[i][j] * M[k][k] - M[i][k] * M[k][j]) // prev
                M[i][k] = 0
            prev = M[k][k]
        return sign * M[n - 1][n - 1]

    def det(m):
        k = len(m)
        if k == 1:
            return m[0][0]
        total = 0
        sign = 1
        for j in range(k):
            minor = [row[:j] + row[j + 1:] for row in m[1:]]
            total += sign * m[0][j] * det(minor)
            sign = -sign
        return total

    return det(M)

