import math

def solve(n):
    """Return the list of all primes strictly below n, ascending."""
    if n <= 2:
        return []
    sieve = bytearray([1]) * n
    sieve[0] = 0
    sieve[1] = 0
    for i in range(2, math.isqrt(n - 1) + 1):
        if sieve[i]:
            start = i * i
            sieve[start:n:i] = bytearray(len(range(start, n, i)))
    return [i for i in range(2, n) if sieve[i]]

