    """Return the count of prime numbers strictly less than n.
    Works for n up to several tens of millions within typical limits.
    """
    if not isinstance(n, int) or n <= 2:
        return 0
    # Sieve of Eratosthenes using a bytearray for memory efficiency.
    limit = n - 1  # highest number we need to consider
    sieve = bytearray(b'\x01') * (limit + 1)
    # 0 and 1 are not prime
    if limit >= 0:
        sieve[0] = 0
    if limit >= 1:
        sieve[1] = 0
    import math
    max_p = int(math.isqrt(limit))
    for p in range(2, max_p + 1):
        if sieve[p]:
            start = p * p
            step = p
            sieve[start:limit + 1:step] = b'\x00' * ((limit - start) // step + 1)
    return int(sieve.count(1))

