def solve(weights, values, capacity):
    """0/1 knapsack returning maximum total value.
    Handles zero-weight items by adding their values directly.
    Uses classic DP with O(capacity) memory.
    """
    # Sum values of zero-weight items (they can always be taken)
    extra = 0
    items = []
    for w, v in zip(weights, values):
        if w == 0:
            if v > 0:
                extra += v
        else:
            items.append((w, v))
    # DP array
    dp = [0] * (capacity + 1)
    for w, v in items:
        # iterate backwards to avoid reusing item
        for c in range(capacity, w - 1, -1):
            new_val = dp[c - w] + v
            if new_val > dp[c]:
                dp[c] = new_val
    return dp[capacity] + extra

