def solve(matrix):
    """Return the determinant of a square integer matrix.
    Empty matrix (0x0) is defined to have determinant 1.
    Uses exact Gaussian elimination with Fractions to avoid floating errors.
    """
    if not matrix:
        return 1
    n = len(matrix)
    # Convert to Fractions for exact arithmetic
    from fractions import Fraction
    a = [[Fraction(x) for x in row] for row in matrix]
    det = Fraction(1)
    for i in range(n):
        # Find a non-zero pivot in column i starting from row i
        pivot = i
        while pivot < n and a[pivot][i] == 0:
            pivot += 1
        if pivot == n:
            return 0
        if pivot != i:
            a[i], a[pivot] = a[pivot], a[i]
            det = -det
        pivot_val = a[i][i]
        det *= pivot_val
        # Eliminate rows below
        for r in range(i + 1, n):
            if a[r][i] != 0:
                factor = a[r][i] / pivot_val
                for c in range(i, n):
                    a[r][c] -= factor * a[i][c]
    # Determinant should be integer
    return int(det)

