def solve(matrix):
    """Return elements of a matrix in clockwise spiral order.
    Handles empty matrix and matrices with empty rows gracefully.
    """
    # Edge cases: empty matrix or first row empty -> no elements
    if not matrix or not any(matrix) or not matrix[0]:
        return []
    top, bottom = 0, len(matrix) - 1
    left, right = 0, len(matrix[0]) - 1
    result = []
    while top <= bottom and left <= right:
        # top row
        for col in range(left, right + 1):
            result.append(matrix[top][col])
        top += 1
        # right column
        for row in range(top, bottom + 1):
            result.append(matrix[row][right])
        right -= 1
        if top <= bottom:
            # bottom row
            for col in range(right, left - 1, -1):
                result.append(matrix[bottom][col])
            bottom -= 1
        if left <= right:
            # left column
            for row in range(bottom, top - 1, -1):
                result.append(matrix[row][left])
            left += 1
    return result

def solve(weights, values, capacity):
    """Return the maximum total value achievable with given weights and values (0/1 knapsack)."""
    n = len(weights)
    if n == 0 or capacity <= 0:
        return 0
    # DP array of size capacity+1, initialized to 0
    dp = [0] * (capacity + 1)
    for i in range(n):
        w = weights[i]
        v = values[i]
        # iterate backwards to avoid reuse
        for c in range(capacity, w - 1, -1):
            new_val = dp[c - w] + v
            if new_val > dp[c]:
                dp[c] = new_val
    return dp[capacity]

